const ROLES_EMAIL = {
  "carmenluzhdiez@gmail.com": "programador", // email inicial del programador — cambiar desde Gestión de Accesos
};
const getRolByEmail = (email, emailsExtra={}) => {
  if(!email) return null;
  const lower = email.toLowerCase();
  if(ROLES_EMAIL[lower]) return ROLES_EMAIL[lower];
  const clave = lower.replace(/\./g,",").replace(/@/g,"_at_");
  for(const [k,v] of Object.entries(emailsExtra||{})) {
    // Formato nuevo: {email, rol}
    if(typeof v==="object" && v!==null && v.email?.toLowerCase()===lower) return v.rol;
    // Formato antiguo: clave codificada → valor string
    if(typeof v==="string" && k===clave) return v;
  }
  return null;
};

// Hook genérico Firebase ↔ React state
// Sincroniza un nodo de Firebase con un estado local.
// defaultValue se usa solo si Firebase devuelve null.
function useFirebaseState(path, defaultValue) {
  const fullPath = `${ROOT}/${path}`;
  const [value, setValueLocal] = useState(defaultValue);
  const [ready,  setReady]     = useState(false);
  const valueRef = useRef(defaultValue); // referencia siempre actualizada
  const pendingRef = useRef(false); // hay una escritura pendiente

  useEffect(() => {
    const fbRef = ref(db, fullPath);
    const unsub = onValue(fbRef, (snap) => {
      if (pendingRef.current) return; // ignorar actualizaciones mientras escribimos
      const snapV = snap.val();
      const newVal = snapV !== null && snapV !== undefined ? snapV : defaultValue;
      valueRef.current = newVal;
      setValueLocal(newVal);
      setReady(true);
    });
    return () => unsub();
  }, [fullPath]);

  const setValue = (newVal) => {
    const resolved = typeof newVal === "function" ? newVal(valueRef.current) : newVal;
    valueRef.current = resolved;
    setValueLocal(resolved);
    pendingRef.current = true;
    fbSet(ref(db, fullPath), resolved)
      .then(() => { setTimeout(() => { pendingRef.current = false; }, 3000); })
      .catch(() => { pendingRef.current = false; });
  };

  const setValueLocalOnly = (newVal) => {
    const resolved = typeof newVal === "function" ? newVal(valueRef.current) : newVal;
    valueRef.current = resolved;
    setValueLocal(resolved);
  };
  return [value, setValue, ready, setValueLocalOnly];
}

