const DIAS_SEMANA_GLOBAL = [
  {v:1,l:"Lun",full:"Lunes"},{v:2,l:"Mar",full:"Martes"},{v:3,l:"Mié",full:"Miércoles"},
  {v:4,l:"Jue",full:"Jueves"},{v:5,l:"Vie",full:"Viernes"},{v:6,l:"Sáb",full:"Sábado"},{v:0,l:"Dom",full:"Domingo"},
];
const frecToDiasGlobal = (frec) => {
  const map = {diario:1,cada2dias:2,cada3dias:3,cada5dias:5,semanal:7,quincenal:15,mensual:30,bimestral:60,trimestral:90,semestral:180,anual:365,unavez:null,segunecesidad:null};
  return map[frec]||null;
};
const estacionDeFecha = (fechaStr) => {
  const mesNum = new Date(fechaStr+"T12:00:00").getMonth()+1;
  return [12,1,2].includes(mesNum)?"verano":[3,4,5].includes(mesNum)?"otono":[6,7,8].includes(mesNum)?"invierno":"primavera";
};
// Calcula la próxima fecha en que corresponde una tarea de frecuencia f, evaluada respecto a una fecha de referencia (refFecha, normalmente "hoy")
const calcProximaFrecGlobal = (f, refFecha) => {
  const ref = new Date(refFecha+"T12:00:00");
  if(f.modo==="diasSemana"){
    if(!f.ultimaVez) return null;
    const minimoDias = Number(f.diasMinimos)||0;
    const prohibidos = f.diasProhibidos||[];
    const hayDiasEspecificos = f.diasSemana && f.diasSemana.length>0;
    const ultima = new Date(f.ultimaVez+"T12:00:00");
    let base = new Date(ultima.getTime() + minimoDias*24*60*60*1000);
    for(let i=0;i<400;i++){
      const candidato = new Date(base.getTime() + i*24*60*60*1000);
      const dow = candidato.getDay();
      if(prohibidos.includes(dow)) continue;
      if(hayDiasEspecificos && !f.diasSemana.includes(dow)) continue;
      const diff = Math.round((candidato-ref)/(24*60*60*1000));
      return { fecha: candidato.toISOString().slice(0,10), diff };
    }
    return null;
  }
  // modo estación — compatible con formato viejo (string) y nuevo (objeto {tipo,cadaDias})
  const estCPFG = estacionDeFecha(refFecha);
  const estValRaw = f[estCPFG];
  let frecVal, dias;
  if(typeof estValRaw === "object" && estValRaw !== null) {
    // Formato nuevo: {tipo:"cadaXdias", cadaDias:"7"}
    if(estValRaw.tipo==="noaplica"||estValRaw.tipo==="segunecesidad") return null;
    const diasMap = {diario:1,cada2dias:2,cada3dias:3,cada4dias:4,cada5dias:5,cada6dias:6,semanal:7,quincenal:15,cada21dias:21,mensual:30,bimestral:60,trimestral:90};
    dias = Number(estValRaw.cadaDias) || diasMap[estValRaw.cadaDias] || null;
    frecVal = String(dias||"");
  } else {
    // Formato viejo: string "semanal","quincenal",etc.
    frecVal = estValRaw;
    if(!frecVal||frecVal==="noaplica"||frecVal==="unavez"||frecVal==="segunecesidad") return null;
    dias = frecToDiasGlobal(frecVal);
  }
  if(!f.ultimaVez) return null;
  if(!dias) return null;
  const ultima = new Date(f.ultimaVez+"T12:00:00");
  const proxima = new Date(ultima.getTime() + dias*24*60*60*1000);
  const diff = Math.round((proxima-ref)/(24*60*60*1000));
  return { fecha: proxima.toISOString().slice(0,10), diff };
};

// ─── Actualiza/revierte "Última realización" de la frecuencia de origen de una tarea ───
// Se llama SIEMPRE que cambia el estado de una tarea con origenZid/origenFrecId (venga de
// Programación Diaria, Historial, o Programación de Golf) para que el comportamiento sea
// idéntico en todos los caminos de la app.
// - Ida (algo -> hecha/completada): fija ultimaVez = fecha de la tarea, guardando el valor previo.
// - Vuelta (hecha/completada -> algo): si la frecuencia sigue apuntando a esta tarea, la revierte
//   al valor previo (evita que quede "al día" una tarea que resultó incompleta).
// Devuelve el patch (posiblemente con ultimaVezPrevia agregado) para que el llamador lo aplique a la tarea.
const aplicarCambioFrecuencia = (tareaVieja, patch, getElemFrecs, setElemFrecs) => {
  if(!tareaVieja || !patch || patch.estado===undefined) return patch;
  if(!tareaVieja.origenZid || !tareaVieja.origenFrecId || !getElemFrecs || !setElemFrecs) return patch;
  const estViejo = normalizarEstado(tareaVieja.estado);
  const estNuevo = normalizarEstado(patch.estado);
  const eraCompletada = estViejo==="hecha"||estViejo==="completada";
  const esCompletada = estNuevo==="hecha"||estNuevo==="completada";
  if(!eraCompletada && esCompletada){
    const frecsActuales = getElemFrecs(tareaVieja.origenZid, tareaVieja.origenEid, null, tareaVieja.origenEsCustom);
    const frecActual = frecsActuales.find(f=>f.id===tareaVieja.origenFrecId);
    const valorPrevio = frecActual?.ultimaVez ?? null;
    const frecsActualizadas = frecsActuales.map(f => f.id===tareaVieja.origenFrecId ? {...f, ultimaVez: tareaVieja.fecha} : f);
    setElemFrecs(tareaVieja.origenZid, tareaVieja.origenEid, tareaVieja.origenEsCustom, frecsActualizadas);
    return {...patch, ultimaVezPrevia: valorPrevio};
  }
  if(eraCompletada && !esCompletada){
    const frecsActuales = getElemFrecs(tareaVieja.origenZid, tareaVieja.origenEid, null, tareaVieja.origenEsCustom);
    const frecActual = frecsActuales.find(f=>f.id===tareaVieja.origenFrecId);
    if(frecActual && frecActual.ultimaVez===tareaVieja.fecha){
      const frecsActualizadas = frecsActuales.map(f=>f.id===tareaVieja.origenFrecId ? {...f, ultimaVez: tareaVieja.ultimaVezPrevia||f.ultimaVez} : f);
      setElemFrecs(tareaVieja.origenZid, tareaVieja.origenEid, tareaVieja.origenEsCustom, frecsActualizadas);
    }
    return {...patch, ultimaVezPrevia: null};
  }
  return patch;
};

